// Returns pseudorandom value between 0 and 1
float rand(in int i) {
  return fract(sin(float(i) * 21370.2137));
}

// Returns pseudorandom normalized vector
vec2 rand_vec(in int i) {
	return normalize(vec2(
		(fract(sin(float(i) * 21370.2137)) - 0.5) * 2.0,
		(fract(sin(float(i) * 21690.4200)) - 0.5) * 2.0
	));
}

// Generates sine wave with given parameters
float generate_sin(in vec2 coord, in float freq, in float amp, in float speed, in vec2 dir) {
	return amp * sin(
		((coord.x * dir.x + coord.y * dir.y)
		* freq / 100.0) + iTime * speed / 2.0
	);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
	int sin_count = 50;
	float val = 0.0;

	// Generate fractal Brownian motion
	for (int i = 1; i <= sin_count; i++) {
		float freq = sqrt(float(i));
		float speed = float(i);
		float gain = 1.0 / (float(i) / 10.0);
		val += generate_sin(fragCoord, freq, gain, speed, rand_vec(i));
	}

	float distortion = val * 2.0;
	float x = (fragCoord.x + distortion) / iResolution.x;
	float y = (fragCoord.y + distortion) / iResolution.y;
	vec4 tex = texture(iChannel0, vec2(x, y));
	float highlight = step(10.0, distortion) * (1.0 - step(12.0, distortion)) * 0.5;
	fragColor = tex + highlight;
}
